import { randomBytes } from "node:crypto";
import { access, mkdir, readFile } from "node:fs/promises";
import { extname, resolve, sep } from "node:path";
import { serve } from "@hono/node-server";
import { createApp } from "./app.ts";
import { OpenCodeSpiritGuide } from "./experience/guide.ts";
import { ExperienceService } from "./experience/service.ts";
import { probeNativeEngine } from "./opencode/client.ts";
import { AtomicProjectStore } from "./store/atomic-project-store.ts";
import { createProject } from "./workflow/model.ts";
import { WorkflowService } from "./workflow/service.ts";

const port = Number(process.env.UB_PORT ?? 4200);
const hostname = "127.0.0.1";
const baseUrl = process.env.OPENCODE_BASE_URL ?? "http://127.0.0.1:4096";
const dataDirectory = resolve(process.env.UB_DATA_DIR ?? ".unfinished-business");
const demoWorkspace = resolve(dataDirectory, "demo-workspace");
const safeDirectory = resolve(dataDirectory, "spirit-workspace");
await mkdir(demoWorkspace, { recursive: true });
await mkdir(safeDirectory, { recursive: true });

const store = new AtomicProjectStore(resolve(dataDirectory, "project.json"));
try {
  await access(store.path);
} catch {
  await store.initialize(createProject(process.cwd()));
}
const sessionToken = process.env.UB_SESSION_TOKEN ?? randomBytes(32).toString("base64url");
const workflow = new WorkflowService(store);
const experience = new ExperienceService(workflow, store, new OpenCodeSpiritGuide({
  baseUrl,
  password: process.env.OPENCODE_PASSWORD,
}), { safeDirectory, demoWorkspace });

const app = createApp(() => probeNativeEngine({
  baseUrl,
  password: process.env.OPENCODE_PASSWORD,
}), { service: workflow, sessionToken, experience });

const webRoot = resolve("dist/web");
const contentTypes: Record<string, string> = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".svg": "image/svg+xml",
  ".json": "application/json",
  ".woff2": "font/woff2",
};

try {
  await access(resolve(webRoot, "index.html"));
  app.get("*", async (context) => {
    if (context.req.path.startsWith("/api")) return context.notFound();
    const requested = context.req.path === "/" ? "index.html" : decodeURIComponent(context.req.path).replace(/^\/+/, "");
    const file = resolve(webRoot, requested);
    if (!file.startsWith(`${webRoot}${sep}`) && file !== resolve(webRoot, "index.html")) return context.notFound();
    try {
      const body = await readFile(file);
      return context.body(body, 200, { "content-type": contentTypes[extname(file)] ?? "application/octet-stream" });
    } catch {
      const index = await readFile(resolve(webRoot, "index.html"));
      return context.body(index, 200, { "content-type": "text/html; charset=utf-8" });
    }
  });
} catch {
  // API-only until the browser bundle has been built.
}

const server = serve({ fetch: app.fetch, hostname, port }, ({ address, port: boundPort }) => {
  console.log(`Unfinished Business listening on http://${address}:${boundPort}`);
});
server.on("error", (error: NodeJS.ErrnoException) => {
  if (error.code === "EADDRINUSE") {
    console.error(`Port ${port} is already in use. Set UB_PORT to a free loopback port.`);
    process.exitCode = 1;
    return;
  }
  throw error;
});
import { Hono } from "hono";
import { z } from "zod";
import { healthSchema, nativeEngineStatusSchema, type NativeEngineStatus } from "../shared/contracts.ts";
import { ExperienceFailure, ExperienceService } from "./experience/service.ts";
import { RevisionConflict } from "./store/atomic-project-store.ts";
import { WorkflowService } from "./workflow/service.ts";
import { approveSection, reviseSection, WorkflowConflict } from "./workflow/transitions.ts";

export type EngineProbe = () => Promise<NativeEngineStatus>;

const actionSchema = z.object({
  actionId: z.string().min(1),
  expectedRevision: z.number().int().nonnegative(),
});
const revisionSchema = actionSchema.extend({ content: z.string().min(1).max(65_536) });
const approvalRequestSchema = actionSchema.extend({
  version: z.number().int().positive(),
  hash: z.string().length(64),
});

const messageSchema = actionSchema.extend({
  intent: z.enum(["clarify", "draft", "question", "witness"]),
  text: z.string().min(1).max(8_000),
});
const approvalKindSchema = z.discriminatedUnion("kind", [
  actionSchema.extend({ kind: z.literal("product") }),
  actionSchema.extend({ kind: z.literal("maker-scope"), statement: z.string().min(8).max(2_000) }),
]);

export interface WorkflowHttpOptions {
  service: WorkflowService;
  sessionToken: string;
  experience?: ExperienceService;
}

export function createApp(probe: EngineProbe, workflow?: WorkflowHttpOptions) {
  const app = new Hono();

  app.get("/api/health", (context) => context.json(healthSchema.parse({
    status: "ok",
    service: "unfinished-business",
  })));

  app.get("/api/engine", async (context) => {
    const status = nativeEngineStatusSchema.parse(await probe());
    return context.json(status, status.available ? 200 : 503);
  });

  if (workflow) {
    app.get("/api/project", async (context) => context.json(await workflow.service.get()));
    app.get("/api/session", (context) => {
      const host = context.req.header("host") ?? "";
      if (!host.startsWith("127.0.0.1") && !host.startsWith("localhost")) {
        return context.json({ code: "INVALID_ORIGIN", message: "The local session token is only available on loopback.", retryable: false }, 403);
      }
      return context.json({ token: workflow.sessionToken });
    });
    if (workflow.experience) {
      app.get("/api/export", async (context) => context.json(await workflow.experience!.exportApproved()));
    }

    app.use("/api/sections/*", async (context, next) => guard(context, next, workflow.sessionToken));
    app.use("/api/messages", async (context, next) => guard(context, next, workflow.sessionToken));
    app.use("/api/approvals", async (context, next) => guard(context, next, workflow.sessionToken));
    app.use("/api/runs", async (context, next) => guard(context, next, workflow.sessionToken));
    app.use("/api/runs/*", async (context, next) => guard(context, next, workflow.sessionToken));

    app.post("/api/sections/:id/revisions", async (context) => {
      try {
        const input = revisionSchema.parse(await context.req.json());
        const result = await workflow.service.execute(
          input.actionId,
          input,
          input.expectedRevision,
          (project) => reviseSection(project, context.req.param("id"), input.content),
        );
        return context.json(result);
      } catch (error) {
        if (error instanceof RevisionConflict || error instanceof WorkflowConflict) {
          return context.json({ code: "WORKFLOW_CONFLICT", message: error.message }, 409);
        }
        if (error instanceof z.ZodError) return context.json({ code: "INVALID_REQUEST", message: "Invalid revision request." }, 400);
        throw error;
      }
    });

    app.post("/api/sections/:id/approve", async (context) => {
      try {
        const input = approvalRequestSchema.parse(await context.req.json());
        const result = await workflow.service.execute(
          input.actionId,
          input,
          input.expectedRevision,
          (project) => approveSection(project, context.req.param("id"), input.version, input.hash),
        );
        return context.json(result);
      } catch (error) {
        if (error instanceof RevisionConflict || error instanceof WorkflowConflict) {
          return context.json({ code: "WORKFLOW_CONFLICT", message: error.message }, 409);
        }
        if (error instanceof z.ZodError) return context.json({ code: "INVALID_REQUEST", message: "Invalid approval request.", retryable: true }, 400);
        throw error;
      }
    });

    app.post("/api/messages", async (context) => {
      if (!workflow.experience) return unavailable(context);
      try {
        const input = messageSchema.parse(await context.req.json());
        const result = await workflow.experience.sendMessage(input.actionId, input.expectedRevision, input.intent, input.text);
        return context.json(result);
      } catch (error) {
        return journeyError(context, error, "Invalid message.");
      }
    });

    app.post("/api/approvals", async (context) => {
      if (!workflow.experience) return unavailable(context);
      try {
        const input = approvalKindSchema.parse(await context.req.json());
        const statement = input.kind === "maker-scope" ? input.statement : undefined;
        const result = await workflow.experience.approve(input.actionId, input.expectedRevision, input.kind, statement);
        return context.json(result);
      } catch (error) {
        return journeyError(context, error, "Invalid approval.");
      }
    });

    app.post("/api/runs", async (context) => {
      if (!workflow.experience) return unavailable(context);
      try {
        const input = actionSchema.parse(await context.req.json());
        const result = await workflow.experience.runMaker(input.actionId, input.expectedRevision);
        return context.json(result);
      } catch (error) {
        return journeyError(context, error, "Invalid Maker run.");
      }
    });

    app.post("/api/runs/:id/cancel", async (context) => {
      if (!workflow.experience) return unavailable(context);
      try {
        const input = actionSchema.parse(await context.req.json());
        const result = await workflow.experience.cancel(input.actionId, input.expectedRevision, context.req.param("id"));
        return context.json(result);
      } catch (error) {
        return journeyError(context, error, "Invalid cancellation.");
      }
    });

    app.post("/api/runs/:id/reconcile", async (context) => {
      if (!workflow.experience) return unavailable(context);
      try {
        const input = actionSchema.parse(await context.req.json());
        const result = await workflow.experience.reconcile(input.actionId, input.expectedRevision, context.req.param("id"));
        return context.json(result);
      } catch (error) {
        return journeyError(context, error, "Invalid reconciliation.");
      }
    });
  }

  return app;
}

async function guard(context: Parameters<Parameters<Hono["use"]>[1]>[0], next: () => Promise<void>, sessionToken: string) {
  if (context.req.method === "GET") return next();
  if (context.req.header("x-ub-session-token") !== sessionToken) {
    return context.json({ code: "INVALID_SESSION", message: "Missing or invalid local browser session token.", retryable: false }, 403);
  }
  return next();
}

function unavailable(context: { json: (body: unknown, status?: number) => Response }) {
  return context.json({ code: "ENGINE_UNAVAILABLE", message: "The workshop journey is not configured.", retryable: false }, 503);
}

function journeyError(context: { json: (body: unknown, status?: number) => Response }, error: unknown, validationMessage: string) {
  if (error instanceof ExperienceFailure) {
    return context.json({
      code: error.code,
      message: error.message,
      retryable: error.retryable,
      operationId: error.operationId,
    }, error.status as 400);
  }
  if (error instanceof RevisionConflict || error instanceof WorkflowConflict) {
    return context.json({ code: "WORKFLOW_CONFLICT", message: error.message, retryable: false }, 409);
  }
  if (error instanceof z.ZodError) return context.json({ code: "INVALID_REQUEST", message: validationMessage, retryable: true }, 400);
  throw error;
}
import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import { App } from "./App.tsx";
import "./styles.css";

createRoot(document.getElementById("root")!).render(
  <StrictMode>
    <App />
  </StrictMode>,
);
import { useEffect, useState } from "react";
import { Eye, Hammer, ScrollText, Sparkles } from "lucide-react";
import { motion, useReducedMotion } from "motion/react";
import {
  ApiError,
  approveProduct,
  approveSection,
  grantScope,
  loadEngine,
  loadExport,
  loadProject,
  reconcileRun,
  reviseSection,
  runMaker,
  sendMessage,
  type EngineStatus,
  type WorkshopProject,
} from "./api.ts";

const spirits = [
  ["ORACLE", "Oracle", Sparkles],
  ["ARCHITECT", "Architect", ScrollText],
  ["MAKER", "Maker", Hammer],
  ["WITNESS", "Witness", Eye],
] as const;

export function App() {
  const [project, setProject] = useState<WorkshopProject | null>(null);
  const [engine, setEngine] = useState<EngineStatus | null>(null);
  const [text, setText] = useState("");
  const [scope, setScope] = useState("Build the approved plan in the isolated demo workspace and leave a passing Node test.");
  const [change, setChange] = useState("");
  const [busy, setBusy] = useState(false);
  const [slow, setSlow] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [exportNote, setExportNote] = useState<string | null>(null);
  const reduceMotion = useReducedMotion();

  useEffect(() => {
    void Promise.all([loadProject(), loadEngine()])
      .then(([loaded, native]) => {
        setProject(loaded);
        setEngine(native);
      })
      .catch((caught: unknown) => {
        setError(caught instanceof Error ? caught.message : "The workshop could not be loaded.");
      });
  }, []);

  async function act(work: () => Promise<{ project: WorkshopProject }>) {
    setBusy(true);
    setSlow(false);
    setError(null);
    const timer = window.setTimeout(() => setSlow(true), 8_000);
    try {
      setProject((await work()).project);
    } catch (caught) {
      const loaded = await loadProject().catch(() => null);
      if (loaded) setProject(loaded);
      setError(caught instanceof ApiError
        ? `${caught.message} ${caught.retryable ? "You can try a new request. The current section was not overwritten." : "Nothing was repeated."}`
        : "The workshop lost its connection. Reload before trying again.");
    } finally {
      window.clearTimeout(timer);
      setBusy(false);
      setSlow(false);
    }
  }

  if (!project) {
    return (
      <main className="workshop">
        <h1>Unfinished Business</h1>
        <p>{error ?? "The workshop is waking up."}</p>
      </main>
    );
  }

  const section = project.sections.find((item) => item.id === project.currentSectionId) ?? null;
  const unknown = project.operations.find((item) => item.status === "UNKNOWN") ?? null;
  const header = project.stage === "ORACLE"
    ? "What's still haunting your to-do list?"
    : section
      ? `${section.title} — section ${section.order} of ${project.sections.length}`
      : project.nextAction;

  return (
    <>
      <a className="skip" href="#document">Skip to the working document</a>
      <main className="workshop">
        <nav className="stage-strip" aria-label="Spirits">
          {spirits.map(([id, label, Icon]) => {
            const done = stageOrder(project.stage) > stageOrder(id);
            return (
              <button key={id} type="button" className={done ? "stage done" : "stage"} aria-current={project.stage === id ? "step" : undefined} disabled>
                <Icon aria-hidden="true" size={18} />
                {label}
              </button>
            );
          })}
        </nav>
        <div className="frame">
          <aside className="side">
            <section className="panel">
              <h2>Outline</h2>
              <ol>
                {project.sections.map((item) => (
                  <li key={item.id} className={item.status === "STALE" ? "ghost" : undefined}>
                    {item.title} — {statusLabel(item)}
                  </li>
                ))}
              </ol>
            </section>
          </aside>
          <article className="document" id="document" aria-busy={busy}>
            <Lantern />
            <p className="eyebrow">{project.stage}</p>
            <h1>
              {header}
              {project.product.status === "APPROVED" && section?.status === "APPROVED" ? (
                <Seal label="Approved" reduceMotion={reduceMotion} />
              ) : null}
            </h1>
            <p className="status-line">Stopped here: {project.nextAction}</p>
            {engine && !engine.available ? (
              <p className="banner bad" role="status">
                {engine.limitation?.includes("fetch failed")
                  ? "OpenCode is not reachable on the configured loopback address."
                  : engine.limitation}{" "}
                Start OpenCode, then try again. No paid model will be used.
              </p>
            ) : null}
            {unknown ? (
              <p className="banner bad" role="status">
                A native run is unknown and was not repeated.
                <button className="action secondary" type="button" disabled={busy} onClick={() => void act(() => reconcileRun(project, unknown.id))}>Reconcile native session</button>
              </p>
            ) : null}
            {slow ? <p className="banner" role="status">This is taking longer than usual. The saved section is unchanged until a response arrives.</p> : null}
            {error ? <p className="banner bad" role="alert">{error}</p> : null}

            {project.stage === "ORACLE" ? (
              <OraclePanel project={project} text={text} setText={setText} busy={busy} act={act} />
            ) : null}
            {project.stage === "ARCHITECT" && section ? (
              <ArchitectPanel
                project={project}
                section={section}
                change={change}
                setChange={setChange}
                text={text}
                setText={setText}
                busy={busy}
                act={act}
                reduceMotion={reduceMotion}
              />
            ) : null}
            {project.stage === "ARCHITECT" && !section ? (
              <ScopePanel project={project} scope={scope} setScope={setScope} busy={busy} act={act} />
            ) : null}
            {project.stage === "MAKER" ? (
              <MakerPanel project={project} busy={busy} act={act} />
            ) : null}
            {project.stage === "WITNESS" ? (
              <WitnessPanel project={project} text={text} setText={setText} busy={busy} act={act} exportNote={exportNote} setExportNote={setExportNote} />
            ) : null}
          </article>
          <aside className="side">
            <Activity project={project} />
          </aside>
        </div>
      </main>
    </>
  );
}

function OraclePanel(props: {
  project: WorkshopProject;
  text: string;
  setText: (value: string) => void;
  busy: boolean;
  act: (work: () => Promise<{ project: WorkshopProject }>) => Promise<void>;
}) {
  const proposal = props.project.product.proposal;
  return (
    <>
      <p>Describe an idea you want to bring to life.</p>
      {proposal ? (
        <div className="reading prose">
          <h2>Oracle proposal</h2>
          <p>{proposal}</p>
          {props.project.product.openQuestions.length ? (
            <ul>{props.project.product.openQuestions.map((question) => <li key={question}>{question}</li>)}</ul>
          ) : null}
        </div>
      ) : null}
      <label>
        Idea or question
        <textarea value={props.text} onChange={(event) => props.setText(event.target.value)} maxLength={8000} />
      </label>
      <div className="actions">
        {proposal ? (
          <button className="action" type="button" disabled={props.busy} onClick={() => void props.act(() => approveProduct(props.project))}>
            Approve product
          </button>
        ) : (
          <button className="action" type="button" disabled={props.busy || props.text.trim().length < 1} onClick={() => void props.act(() => sendMessage(props.project, "clarify", props.text))}>
            Wake the Oracle
          </button>
        )}
        {proposal ? (
          <button className="action secondary" type="button" disabled={props.busy || props.text.trim().length < 1} onClick={() => void props.act(() => sendMessage(props.project, "question", props.text))}>
            Ask a question
          </button>
        ) : null}
      </div>
    </>
  );
}

import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";

export default defineConfig({
  plugins: [react()],
  build: {
    outDir: "dist/web",
    emptyOutDir: true,
  },
  server: {
    host: "127.0.0.1",
    port: 5173,
    proxy: {
      "/api": `http://127.0.0.1:${process.env.UB_PORT ?? "4200"}`,
    },
  },
});
{
  "compilerOptions": {
    "target": "ES2023",
    "lib": ["ES2023", "DOM", "DOM.Iterable"],
    "module": "ESNext",
    "moduleResolution": "Bundler",
    "jsx": "react-jsx",
    "strict": true,
    "noEmit": true,
    "skipLibCheck": true,
    "allowImportingTsExtensions": true,
    "resolveJsonModule": true,
    "types": ["node"]
  },
  "include": ["src", "tests", "vite.config.ts"]
}
